:root {
  --bg: #0d1b2a;
  --bg-elev: #1b2838;
  --bg-soft: #223447;
  --text: #e8f1f8;
  --muted: #a9bfce;
  --accent: #00b4d8;
  --accent-2: #0077b6;
  --success: #2dd4bf;
  --danger: #fb7185;
  --border: rgba(167, 196, 216, 0.24);
  --shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  --radius: 14px;
  --container: 1160px;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(circle at top right, #12263b 0%, var(--bg) 45%, #09131f 100%);
  color: var(--text);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(100% - 2rem, var(--container)); margin-inline: auto; }
.section { padding: 4.5rem 0; }
.card {
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  backdrop-filter: blur(12px);
  background: rgba(11, 24, 38, 0.9);
  border-bottom: 1px solid rgba(167, 196, 216, 0.16);
}
.header-inner {
  min-height: 74px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.2px;
}
.brand-mark {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: linear-gradient(140deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 0 1px rgba(255,255,255,0.15) inset;
}
.nav {
  display: flex;
  align-items: center;
  gap: 1.1rem;
}
.nav-link {
  color: var(--muted);
  font-weight: 500;
}
.nav-link:hover,
.nav-link:focus-visible,
.nav-link.active { color: var(--text); }
.dropdown {
  position: relative;
}
.dropdown-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  background: transparent;
  color: var(--muted);
  border: 0;
  font: inherit;
  cursor: pointer;
  padding: 0;
}
.dropdown-toggle:hover,
.dropdown-toggle:focus-visible { color: var(--text); }
.dropdown-menu {
  position: absolute;
  top: calc(100% + 0.85rem);
  left: 0;
  min-width: 220px;
  background: #102133;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0.55rem;
  display: none;
}
.dropdown.open .dropdown-menu { display: block; }
.dropdown-item {
  display: block;
  padding: 0.65rem 0.75rem;
  border-radius: 8px;
  color: var(--muted);
}
.dropdown-item:hover,
.dropdown-item:focus-visible,
.dropdown-item.active {
  color: var(--text);
  background: rgba(0, 180, 216, 0.15);
}

.btn {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 0.4rem;
  min-height: 44px;
  padding: 0.75rem 1.2rem;
  border-radius: 10px;
  border: 1px solid transparent;
  font-weight: 600;
  cursor: pointer;
  transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;
}
.btn:focus-visible { outline: 2px solid #7dd3fc; outline-offset: 2px; }
.btn-primary {
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #f4fbff;
}
.btn-primary:hover { transform: translateY(-1px); }
.btn-ghost {
  border-color: var(--border);
  color: var(--text);
  background: rgba(255,255,255,0.01);
}

.hero {
  padding: 5rem 0 3rem;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: 2rem;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  gap: 0.5rem;
  align-items: center;
  color: #8adcf0;
  font-size: 0.9rem;
  letter-spacing: 0.25px;
}
.eyebrow-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--success);
}
h1, h2, h3 { line-height: 1.2; margin: 0 0 0.8rem; }
h1 { font-size: clamp(2rem, 4vw, 3.3rem); }
h2 { font-size: clamp(1.6rem, 3vw, 2.3rem); }
p { margin: 0 0 1rem; color: var(--muted); }
.hero-actions { display: flex; gap: 0.75rem; flex-wrap: wrap; margin-top: 1.2rem; }

.diagram {
  padding: 1.2rem;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: linear-gradient(180deg, rgba(0,180,216,0.08), rgba(0,0,0,0));
}
.diagram svg { width: 100%; height: auto; }

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  margin-bottom: 1rem;
}
.tab-btn {
  min-height: 44px;
  border-radius: 999px;
  border: 1px solid var(--border);
  padding: 0.55rem 1rem;
  background: rgba(255,255,255,0.02);
  color: var(--muted);
  font-weight: 600;
  cursor: pointer;
}
.tab-btn.active {
  background: linear-gradient(140deg, rgba(0,180,216,0.25), rgba(0,119,182,0.3));
  color: var(--text);
  border-color: rgba(0,180,216,0.5);
}
.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fade 220ms ease; }
@keyframes fade { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }

.grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.use-case-card, .feature-card, .info-card { padding: 1.15rem; }
.use-case-card h3, .feature-card h3, .info-card h3 { margin-bottom: 0.35rem; font-size: 1.06rem; }

.accordion-item { border-top: 1px solid var(--border); }
.accordion-trigger {
  width: 100%;
  text-align: left;
  min-height: 52px;
  padding: 0.9rem 0;
  background: transparent;
  color: var(--text);
  border: 0;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 600;
}
.accordion-content { display: none; padding-bottom: 1rem; color: var(--muted); }
.accordion-item.active .accordion-content { display: block; }

.stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}
.stat {
  padding: 1rem;
  text-align: center;
}
.stat-circle {
  width: 120px;
  height: 120px;
  border-radius: 999px;
  margin: 0 auto 0.75rem;
  background: conic-gradient(var(--accent) calc(var(--pct) * 1%), #163247 0);
  display: grid;
  place-items: center;
}
.stat-inner {
  width: 90px;
  height: 90px;
  border-radius: 999px;
  background: #0f2234;
  display: grid;
  place-items: center;
  font-weight: 700;
  color: #dcf6ff;
}
.timeline-item { padding: 1rem; }
.progress {
  height: 10px;
  border-radius: 999px;
  background: #102132;
  overflow: hidden;
  border: 1px solid rgba(167, 196, 216, 0.2);
}
.progress > span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent-2));
}

.carousel-dots { display: flex; gap: 0.4rem; justify-content: center; margin-top: 1rem; }
.dot {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: transparent;
  cursor: pointer;
}
.dot.active { background: var(--accent); border-color: var(--accent); }

.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.9rem; }
.form-field { display: grid; gap: 0.35rem; }
label { font-weight: 600; font-size: 0.95rem; }
input, select, textarea {
  width: 100%;
  min-height: 44px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #102233;
  color: var(--text);
  padding: 0.7rem 0.8rem;
}
textarea { min-height: 120px; resize: vertical; }
.error { color: var(--danger); font-size: 0.85rem; min-height: 1em; }

.cookie-banner {
  position: fixed;
  left: 1rem;
  right: 1rem;
  bottom: 1rem;
  padding: 1rem;
  z-index: 120;
  display: none;
}
.cookie-banner.show { display: flex; gap: 0.9rem; justify-content: space-between; align-items: center; flex-wrap: wrap; }

.footer { border-top: 1px solid rgba(167, 196, 216, 0.16); padding: 2rem 0; color: var(--muted); }

@media (max-width: 980px) {
  .hero-grid, .grid-3, .stats { grid-template-columns: 1fr 1fr; }
  .nav { display: none; }
}
@media (max-width: 720px) {
  .hero-grid, .grid-3, .grid-2, .stats, .form-grid { grid-template-columns: 1fr; }
  .hero { padding-top: 3rem; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const current = window.location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('[data-nav]').forEach((el) => {
    if (el.getAttribute('href') === current) el.classList.add('active');
  });

  document.querySelectorAll('.dropdown-toggle').forEach((toggle) => {
    const dropdown = toggle.closest('.dropdown');
    toggle.addEventListener('click', () => dropdown.classList.toggle('open'));
    document.addEventListener('click', (e) => {
      if (!dropdown.contains(e.target)) dropdown.classList.remove('open');
    });
  });

  document.querySelectorAll('[data-tab-group]').forEach((group) => {
    const buttons = group.querySelectorAll('[data-tab-target]');
    const panels = group.querySelectorAll('[data-tab-panel]');
    buttons.forEach((btn) => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-tab-target');
        buttons.forEach((b) => b.classList.remove('active'));
        panels.forEach((p) => p.classList.remove('active'));
        btn.classList.add('active');
        group.querySelector(`[data-tab-panel="${target}"]`)?.classList.add('active');
      });
    });
  });

  document.querySelectorAll('[data-accordion]').forEach((root) => {
    const items = root.querySelectorAll('.accordion-item');
    items.forEach((item) => {
      const trigger = item.querySelector('.accordion-trigger');
      trigger.addEventListener('click', () => {
        items.forEach((it) => it.classList.remove('active'));
        item.classList.add('active');
      });
    });
  });

  document.querySelectorAll('[data-carousel]').forEach((root) => {
    const slides = root.querySelectorAll('[data-slide]');
    const dots = root.querySelectorAll('.dot');
    dots.forEach((dot, idx) => {
      dot.addEventListener('click', () => {
        slides.forEach((s) => s.classList.remove('active'));
        dots.forEach((d) => d.classList.remove('active'));
        slides[idx].classList.add('active');
        dot.classList.add('active');
      });
    });
  });

  const cookieKey = 'wellstream_cookie_pref';
  const banner = document.querySelector('#cookie-banner');
  if (banner && !localStorage.getItem(cookieKey)) {
    banner.classList.add('show');
    banner.querySelectorAll('[data-cookie]').forEach((btn) => {
      btn.addEventListener('click', () => {
        localStorage.setItem(cookieKey, btn.getAttribute('data-cookie'));
        banner.classList.remove('show');
      });
    });
  }

  const demoForm = document.querySelector('#demo-form');
  if (demoForm) {
    demoForm.addEventListener('submit', (e) => {
      e.preventDefault();
      let valid = true;
      demoForm.querySelectorAll('[data-required]').forEach((field) => {
        const error = demoForm.querySelector(`[data-error-for="${field.name}"]`);
        if (!field.value.trim()) {
          valid = false;
          if (error) error.textContent = 'This field is required.';
        } else if (field.type === 'email' && !/^\S+@\S+\.\S+$/.test(field.value)) {
          valid = false;
          if (error) error.textContent = 'Enter a valid email address.';
        } else {
          if (error) error.textContent = '';
        }
      });
      const status = document.querySelector('#form-status');
      if (valid) {
        status.textContent = 'Thank you. Your demo request has been submitted.';
        status.style.color = '#2dd4bf';
        demoForm.reset();
      } else {
        status.textContent = 'Please fix highlighted fields and resubmit.';
        status.style.color = '#fb7185';
      }
    });
  }
})();
EOF

